const steps = [{"id":"intro","title":"1. Lógica e Algoritmos","type":"theory","objective":"Entender o que é lógica antes de programar.","html":"\n<h3>O que é lógica de programação?</h3>\n<p><strong>Lógica de programação</strong> é a forma organizada de pensar em passos para resolver um problema. Antes de escrever código, o programador precisa entender: quais dados entram, o que será feito com eles e qual resultado deve sair.</p>\n<div class=\"theory-grid\">\n  <div class=\"theory-box\"><h4>Entrada</h4><p>São os dados recebidos. Exemplo: duas notas digitadas pelo usuário.</p></div>\n  <div class=\"theory-box\"><h4>Processamento</h4><p>É o cálculo ou decisão feita com os dados. Exemplo: calcular a média.</p></div>\n  <div class=\"theory-box\"><h4>Saída</h4><p>É o resultado exibido. Exemplo: mostrar se o aluno foi aprovado.</p></div>\n</div>\n<h3>O que é algoritmo?</h3>\n<p>Um <strong>algoritmo</strong> é uma sequência finita, ordenada e lógica de passos para resolver uma tarefa. Uma receita, uma rota no mapa e um manual de montagem são exemplos de algoritmos fora do computador.</p>\n<div class=\"example-card\"><h4>Exemplo prático sem programação</h4><ol><li>Pegar duas notas do aluno.</li><li>Somar as duas notas.</li><li>Dividir o resultado por 2.</li><li>Mostrar a média.</li><li>Se a média for maior ou igual a 6, informar aprovação.</li></ol></div>\n<div class=\"exercise\"><h4>Exercício proposto</h4><p>Escreva, em português comum, um algoritmo para calcular o troco de uma compra. Pense em entrada, processamento e saída.</p></div>\n"},{"id":"fluxo","title":"2. Fluxogramas","type":"theory","objective":"Representar algoritmos com símbolos visuais.","html":"\n<h3>O que é fluxograma?</h3>\n<p>Fluxograma é uma representação visual de um algoritmo. Ele mostra o caminho que a solução percorre, usando símbolos padronizados ligados por setas.</p>\n<div class=\"symbols-grid\">\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 80\"><rect x=\"25\" y=\"18\" width=\"130\" height=\"44\" rx=\"22\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"3\"/><text x=\"90\" y=\"46\" text-anchor=\"middle\">Início/Fim</text></svg><strong>Terminal</strong><span>Marca começo ou término.</span></div>\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 80\"><polygon points=\"45,20 160,20 135,60 20,60\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"90\" y=\"46\" text-anchor=\"middle\">Entrada/Saída</text></svg><strong>Paralelogramo</strong><span>Leitura de dados ou exibição de resultado.</span></div>\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 80\"><rect x=\"30\" y=\"20\" width=\"120\" height=\"40\" fill=\"#fef3c7\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"90\" y=\"46\" text-anchor=\"middle\">Processo</text></svg><strong>Retângulo</strong><span>Cálculo, atribuição ou processamento.</span></div>\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 90\"><polygon points=\"90,10 160,45 90,80 20,45\" fill=\"#fee2e2\" stroke=\"#b91c1c\" stroke-width=\"3\"/><text x=\"90\" y=\"50\" text-anchor=\"middle\">Condição?</text></svg><strong>Losango</strong><span>Decisão com respostas como Sim/Não.</span></div>\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 80\"><line x1=\"25\" y1=\"40\" x2=\"145\" y2=\"40\" stroke=\"#334155\" stroke-width=\"4\"/><polygon points=\"145,30 165,40 145,50\" fill=\"#334155\"/><text x=\"90\" y=\"25\" text-anchor=\"middle\">Fluxo</text></svg><strong>Seta</strong><span>Indica a ordem dos passos.</span></div>\n  <div class=\"symbol-card\"><svg viewBox=\"0 0 180 80\"><circle cx=\"90\" cy=\"40\" r=\"24\" fill=\"#ede9fe\" stroke=\"#6d28d9\" stroke-width=\"3\"/><text x=\"90\" y=\"46\" text-anchor=\"middle\">A</text></svg><strong>Conector</strong><span>Liga partes do fluxograma.</span></div>\n</div>\n<h3>Exemplo 1 — sequência: calcular média</h3>\n<div class=\"flow-wrap\">\n<svg class=\"flow-svg\" viewBox=\"0 0 760 220\">\n<defs><marker id=\"arrow\" markerWidth=\"10\" markerHeight=\"10\" refX=\"9\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L0,6 L9,3 z\" fill=\"#334155\"/></marker></defs>\n<rect x=\"30\" y=\"80\" width=\"120\" height=\"48\" rx=\"24\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"3\"/><text x=\"90\" y=\"110\" text-anchor=\"middle\">Início</text>\n<line x1=\"150\" y1=\"104\" x2=\"215\" y2=\"104\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow)\"/>\n<polygon points=\"230,80 370,80 345,128 205,128\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"287\" y=\"109\" text-anchor=\"middle\">Ler n1, n2</text>\n<line x1=\"370\" y1=\"104\" x2=\"430\" y2=\"104\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow)\"/>\n<rect x=\"445\" y=\"80\" width=\"130\" height=\"48\" fill=\"#fef3c7\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"510\" y=\"109\" text-anchor=\"middle\">m=(n1+n2)/2</text>\n<line x1=\"575\" y1=\"104\" x2=\"625\" y2=\"104\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow)\"/>\n<polygon points=\"640,80 750,80 730,128 620,128\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"685\" y=\"109\" text-anchor=\"middle\">Mostrar m</text>\n</svg>\n</div>\n<h3>Exemplo 2 — decisão: aprovado ou reprovado</h3>\n<div class=\"flow-wrap\"><svg class=\"flow-svg\" viewBox=\"0 0 760 420\">\n<defs><marker id=\"arrow2\" markerWidth=\"10\" markerHeight=\"10\" refX=\"9\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L0,6 L9,3 z\" fill=\"#334155\"/></marker></defs>\n<rect x=\"320\" y=\"15\" width=\"120\" height=\"45\" rx=\"23\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"3\"/><text x=\"380\" y=\"43\" text-anchor=\"middle\">Início</text>\n<line x1=\"380\" y1=\"60\" x2=\"380\" y2=\"95\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow2)\"/>\n<polygon points=\"310,105 480,105 450,155 280,155\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"380\" y=\"135\" text-anchor=\"middle\">Ler nota1, nota2</text>\n<line x1=\"380\" y1=\"155\" x2=\"380\" y2=\"190\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow2)\"/>\n<rect x=\"300\" y=\"200\" width=\"160\" height=\"48\" fill=\"#fef3c7\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"380\" y=\"229\" text-anchor=\"middle\">media=(n1+n2)/2</text>\n<line x1=\"380\" y1=\"248\" x2=\"380\" y2=\"280\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow2)\"/>\n<polygon points=\"380,285 485,335 380,385 275,335\" fill=\"#fee2e2\" stroke=\"#b91c1c\" stroke-width=\"3\"/><text x=\"380\" y=\"340\" text-anchor=\"middle\">media ≥ 6?</text>\n<line x1=\"275\" y1=\"335\" x2=\"150\" y2=\"335\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow2)\"/><text x=\"212\" y=\"322\" text-anchor=\"middle\">Sim</text>\n<polygon points=\"25,310 165,310 140,360 0,360\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\" transform=\"translate(20,0)\"/><text x=\"92\" y=\"340\" text-anchor=\"middle\">Mostrar aprovado</text>\n<line x1=\"485\" y1=\"335\" x2=\"610\" y2=\"335\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow2)\"/><text x=\"548\" y=\"322\" text-anchor=\"middle\">Não</text>\n<polygon points=\"595,310 745,310 720,360 570,360\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"657\" y=\"340\" text-anchor=\"middle\">Mostrar reprovado</text>\n</svg></div>\n<h3>Exemplo 3 — repetição: contar de 1 até 5</h3>\n<div class=\"flow-wrap\"><svg class=\"flow-svg\" viewBox=\"0 0 760 470\">\n<defs><marker id=\"arrow3\" markerWidth=\"10\" markerHeight=\"10\" refX=\"9\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L0,6 L9,3 z\" fill=\"#334155\"/></marker></defs>\n<rect x=\"320\" y=\"15\" width=\"120\" height=\"45\" rx=\"23\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"3\"/><text x=\"380\" y=\"43\" text-anchor=\"middle\">Início</text>\n<line x1=\"380\" y1=\"60\" x2=\"380\" y2=\"95\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/>\n<rect x=\"315\" y=\"105\" width=\"130\" height=\"48\" fill=\"#fef3c7\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"380\" y=\"135\" text-anchor=\"middle\">contador = 1</text>\n<line x1=\"380\" y1=\"153\" x2=\"380\" y2=\"190\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/>\n<polygon points=\"380,200 485,250 380,300 275,250\" fill=\"#fee2e2\" stroke=\"#b91c1c\" stroke-width=\"3\"/><text x=\"380\" y=\"255\" text-anchor=\"middle\">contador ≤ 5?</text>\n<line x1=\"380\" y1=\"300\" x2=\"380\" y2=\"335\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/><text x=\"405\" y=\"322\">Sim</text>\n<polygon points=\"310,345 470,345 440,395 280,395\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"3\"/><text x=\"380\" y=\"375\" text-anchor=\"middle\">Mostrar contador</text>\n<line x1=\"380\" y1=\"395\" x2=\"380\" y2=\"425\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/>\n<rect x=\"300\" y=\"430\" width=\"160\" height=\"35\" fill=\"#fef3c7\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"380\" y=\"454\" text-anchor=\"middle\">contador += 1</text>\n<path d=\"M300 448 H185 V250 H275\" fill=\"none\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/>\n<line x1=\"485\" y1=\"250\" x2=\"610\" y2=\"250\" stroke=\"#334155\" stroke-width=\"3\" marker-end=\"url(#arrow3)\"/><text x=\"548\" y=\"237\" text-anchor=\"middle\">Não</text>\n<rect x=\"620\" y=\"227\" width=\"110\" height=\"45\" rx=\"23\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"3\"/><text x=\"675\" y=\"255\" text-anchor=\"middle\">Fim</text>\n</svg></div>\n<div class=\"exercise\"><h4>Exercício proposto</h4><p>Desenhe um fluxograma para ler a idade de uma pessoa e mostrar se ela é maior de idade ou menor de idade.</p></div>\n"},{"title":"3. Primeiro programa","type":"practice","objective":"Conhecer print() e a estrutura mínima de um programa.","code":"print(\"Olá, mundo!\")\nprint(\"Meu primeiro programa em Python\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nOlá, mundo!\nMeu primeiro programa em Python\n>>>","work":"<h4>Conceitos</h4>\n<p>Um programa em Python pode começar com comandos diretos. Diferente de algumas linguagens, Python não exige uma estrutura inicial grande para executar um código simples.</p>\n<h4>Sintaxe trabalhada</h4>\n<pre>print(valor)</pre>\n<p><strong>print()</strong> mostra informações na tela do Shell do IDLE.</p>\n<h4>Observação</h4>\n<p>Textos devem ficar entre aspas simples ou duplas.</p>","exercise":"Crie um programa que mostre seu nome, sua turma e uma frase de boas-vindas.","id":"step3"},{"title":"4. Comentários","type":"practice","objective":"Usar comentários para explicar o código.","code":"# Este programa mostra uma mensagem na tela\nprint(\"Estudando Python no IDLE\")\n\n# A linha abaixo mostra outra mensagem\nprint(\"Comentários ajudam a entender o código\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nEstudando Python no IDLE\nComentários ajudam a entender o código\n>>>","work":"<h4>Conceitos</h4><p>Comentários são textos ignorados pelo Python. Servem para explicar o raciocínio do programa.</p>\n<h4>Sintaxe trabalhada</h4><pre># comentário de uma linha</pre><p>Tudo que vem depois de <strong>#</strong> na mesma linha não é executado.</p>","exercise":"Escreva um programa com três comandos print() e coloque um comentário explicando cada um.","id":"step4"},{"title":"5. Variáveis","type":"practice","objective":"Guardar valores na memória.","code":"nome = \"Ana\"\nidade = 15\naltura = 1.65\naprovado = True\n\nprint(\"Nome:\", nome)\nprint(\"Idade:\", idade)\nprint(\"Altura:\", altura)\nprint(\"Aprovado:\", aprovado)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nNome: Ana\nIdade: 15\nAltura: 1.65\nAprovado: True\n>>>","work":"<h4>Conceitos</h4><p>Variável é um nome que guarda um valor na memória. Em Python, o tipo é reconhecido automaticamente conforme o valor atribuído.</p>\n<h4>Sintaxe trabalhada</h4><pre>nome_da_variavel = valor</pre><p>O sinal <strong>=</strong> faz atribuição: coloca um valor dentro de uma variável.</p>\n<h4>Tipos usados</h4><ul><li><strong>str</strong>: texto</li><li><strong>int</strong>: inteiro</li><li><strong>float</strong>: número decimal</li><li><strong>bool</strong>: verdadeiro ou falso</li></ul>","exercise":"Crie variáveis para nome de um produto, preço, quantidade em estoque e se está disponível.","id":"step5"},{"title":"6. Entrada de dados","type":"practice","objective":"Ler dados digitados pelo usuário com input().","code":"nome = input(\"Digite seu nome: \")\nidade = input(\"Digite sua idade: \")\n\nprint(\"Olá,\", nome)\nprint(\"Você tem\", idade, \"anos\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nDigite seu nome: Ana\nDigite sua idade: 15\nOlá, Ana\nVocê tem 15 anos\n>>>","work":"<h4>Conceitos</h4><p>Entrada de dados é quando o programa recebe informações do usuário pelo teclado.</p>\n<h4>Sintaxe trabalhada</h4><pre>variavel = input(\"Mensagem: \")</pre><p>O <strong>input()</strong> sempre devolve texto. Mesmo que o usuário digite número, o valor inicialmente será uma string.</p>","exercise":"Faça um programa que leia nome, cidade e escola do aluno e depois mostre esses dados na tela.","id":"step6"},{"title":"7. Conversão de tipos","type":"practice","objective":"Converter textos digitados em números.","code":"idade = int(input(\"Digite sua idade: \"))\naltura = float(input(\"Digite sua altura: \"))\n\nprint(\"No ano que vem você terá\", idade + 1, \"anos\")\nprint(\"Altura informada:\", altura)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nDigite sua idade: 15\nDigite sua altura: 1.65\nNo ano que vem você terá 16 anos\nAltura informada: 1.65\n>>>","work":"<h4>Conceitos</h4><p>Conversão de tipos transforma um valor de um tipo para outro. É essencial quando usamos números digitados com input().</p>\n<h4>Sintaxe trabalhada</h4><pre>int(valor)\nfloat(valor)\nstr(valor)</pre><ul><li><strong>int()</strong>: converte para inteiro.</li><li><strong>float()</strong>: converte para número decimal.</li><li><strong>str()</strong>: converte para texto.</li></ul>","exercise":"Leia dois números inteiros e mostre a soma entre eles.","id":"step7"},{"title":"8. Operadores aritméticos","type":"practice","objective":"Realizar cálculos básicos.","code":"a = 10\nb = 3\n\nprint(\"Soma:\", a + b)\nprint(\"Subtração:\", a - b)\nprint(\"Multiplicação:\", a * b)\nprint(\"Divisão:\", a / b)\nprint(\"Divisão inteira:\", a // b)\nprint(\"Resto:\", a % b)\nprint(\"Potência:\", a ** b)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nSoma: 13\nSubtração: 7\nMultiplicação: 30\nDivisão: 3.3333333333333335\nDivisão inteira: 3\nResto: 1\nPotência: 1000\n>>>","work":"<h4>Conceitos</h4><p>Operadores aritméticos permitem fazer cálculos matemáticos.</p>\n<h4>Sintaxe trabalhada</h4><pre>+   soma\n-   subtração\n*   multiplicação\n/   divisão real\n//  divisão inteira\n%   resto da divisão\n**  potência</pre>","exercise":"Leia o preço de um produto e aplique 10% de desconto.","id":"step8"},{"title":"9. Operadores relacionais e lógicos","type":"practice","objective":"Comparar valores e montar condições.","code":"idade = 18\ntem_documento = True\n\nprint(\"É maior de idade?\", idade >= 18)\nprint(\"Pode entrar?\", idade >= 18 and tem_documento)\nprint(\"Menor de idade?\", not idade >= 18)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nÉ maior de idade? True\nPode entrar? True\nMenor de idade? False\n>>>","work":"<h4>Conceitos</h4><p>Operadores relacionais comparam valores. Operadores lógicos combinam condições.</p>\n<h4>Sintaxe trabalhada</h4><pre>== igual\n!= diferente\n>  maior\n<  menor\n>= maior ou igual\n<= menor ou igual\n\nand  E lógico\nor   OU lógico\nnot  NÃO lógico</pre>\n<p>O resultado de uma comparação é sempre <strong>True</strong> ou <strong>False</strong>.</p>","exercise":"Crie um programa que leia a idade e mostre se ela está entre 12 e 17 anos.","id":"step9"},{"title":"10. Condicional if","type":"practice","objective":"Tomar decisões no programa.","code":"media = float(input(\"Digite a média: \"))\n\nif media >= 6:\n    print(\"Aprovado\")\nelse:\n    print(\"Reprovado\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nDigite a média: 7.5\nAprovado\n>>>","work":"<h4>Conceitos</h4><p>Condicional é uma estrutura de decisão. O programa escolhe um caminho conforme uma condição.</p>\n<h4>Sintaxe trabalhada</h4><pre>if condição:\n    comandos\nelse:\n    comandos</pre><p>Em Python, os blocos dependem da <strong>indentação</strong>. O espaço no começo da linha faz parte da estrutura.</p>","exercise":"Leia a idade de uma pessoa e mostre “Maior de idade” ou “Menor de idade”.","id":"step10"},{"title":"11. if, elif e else","type":"practice","objective":"Trabalhar com várias possibilidades.","code":"nota = float(input(\"Digite a nota: \"))\n\nif nota >= 9:\n    print(\"Excelente\")\nelif nota >= 6:\n    print(\"Aprovado\")\nelif nota >= 4:\n    print(\"Recuperação\")\nelse:\n    print(\"Reprovado\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nDigite a nota: 5\nRecuperação\n>>>","work":"<h4>Conceitos</h4><p>Quando existem mais de dois caminhos possíveis, usamos <strong>elif</strong>, que significa “senão se”.</p>\n<h4>Sintaxe trabalhada</h4><pre>if condição1:\n    comandos\nelif condição2:\n    comandos\nelse:\n    comandos</pre><p>O Python testa as condições de cima para baixo e executa o primeiro bloco verdadeiro.</p>","exercise":"Leia a temperatura e classifique como frio, agradável ou quente.","id":"step11"},{"title":"12. Repetição while","type":"practice","objective":"Repetir enquanto uma condição for verdadeira.","code":"contador = 1\n\nwhile contador <= 5:\n    print(\"Contagem:\", contador)\n    contador = contador + 1\n\nprint(\"Fim\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nContagem: 1\nContagem: 2\nContagem: 3\nContagem: 4\nContagem: 5\nFim\n>>>","work":"<h4>Conceitos</h4><p>O <strong>while</strong> repete comandos enquanto a condição for verdadeira.</p>\n<h4>Sintaxe trabalhada</h4><pre>while condição:\n    comandos</pre><p>É importante alterar a variável de controle para evitar repetição infinita.</p>","exercise":"Faça uma contagem regressiva de 10 até 1 usando while.","id":"step12"},{"title":"13. Repetição for","type":"practice","objective":"Repetir com sequência controlada.","code":"for numero in range(1, 6):\n    print(\"Número:\", numero)\n\nprint(\"Fim da repetição\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nNúmero: 1\nNúmero: 2\nNúmero: 3\nNúmero: 4\nNúmero: 5\nFim da repetição\n>>>","work":"<h4>Conceitos</h4><p>O <strong>for</strong> percorre uma sequência. Com <strong>range()</strong>, ele gera uma sequência de números.</p>\n<h4>Sintaxe trabalhada</h4><pre>for variavel in range(inicio, fim):\n    comandos</pre><p>O valor final do range não entra. <code>range(1, 6)</code> gera 1, 2, 3, 4 e 5.</p>","exercise":"Mostre a tabuada de um número usando for.","id":"step13"},{"title":"14. Listas","type":"practice","objective":"Guardar vários valores em uma única variável.","code":"nomes = [\"Ana\", \"Bruno\", \"Carlos\"]\n\nprint(\"Primeiro nome:\", nomes[0])\nprint(\"Todos os nomes:\")\n\nfor nome in nomes:\n    print(nome)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nPrimeiro nome: Ana\nTodos os nomes:\nAna\nBruno\nCarlos\n>>>","work":"<h4>Conceitos</h4><p>Lista é uma estrutura que armazena vários valores em ordem.</p>\n<h4>Sintaxe trabalhada</h4><pre>lista = [valor1, valor2, valor3]\nlista[indice]</pre><p>Em Python, o primeiro índice é <strong>0</strong>.</p>","exercise":"Crie uma lista com cinco produtos e mostre todos usando for.","id":"step14"},{"title":"15. Matrizes","type":"practice","objective":"Representar tabelas com listas dentro de listas.","code":"notas = [\n    [7.0, 8.0],\n    [6.5, 9.0],\n    [5.0, 6.0]\n]\n\nprint(\"Nota do primeiro aluno na primeira prova:\", notas[0][0])\n\nfor linha in notas:\n    print(linha)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nNota do primeiro aluno na primeira prova: 7.0\n[7.0, 8.0]\n[6.5, 9.0]\n[5.0, 6.0]\n>>>","work":"<h4>Conceitos</h4><p>Matriz pode ser representada em Python como uma lista de listas. É útil para dados em formato de tabela.</p>\n<h4>Sintaxe trabalhada</h4><pre>matriz = [[a, b], [c, d]]\nmatriz[linha][coluna]</pre><p>Linhas e colunas também começam no índice 0.</p>","exercise":"Monte uma matriz 2x3 com números inteiros e mostre seus valores linha por linha.","id":"step15"},{"title":"16. Funções","type":"practice","objective":"Organizar o código em blocos reutilizáveis.","code":"def saudacao(nome):\n    print(\"Olá,\", nome)\n\nsaudacao(\"Ana\")\nsaudacao(\"Bruno\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nOlá, Ana\nOlá, Bruno\n>>>","work":"<h4>Conceitos</h4><p>Função é um bloco de código com nome. Ela ajuda a organizar e reaproveitar comandos.</p>\n<h4>Sintaxe trabalhada</h4><pre>def nome_da_funcao(parametros):\n    comandos</pre><p>Para executar a função, chamamos seu nome e passamos os valores necessários.</p>","exercise":"Crie uma função que receba o nome de um aluno e mostre uma mensagem de boas-vindas.","id":"step16"},{"title":"17. Funções com retorno","type":"practice","objective":"Calcular e devolver valores.","code":"def calcular_media(n1, n2):\n    media = (n1 + n2) / 2\n    return media\n\nresultado = calcular_media(7, 9)\nprint(\"Média:\", resultado)","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nMédia: 8.0\n>>>","work":"<h4>Conceitos</h4><p>Uma função pode devolver um resultado para ser usado em outra parte do programa.</p>\n<h4>Sintaxe trabalhada</h4><pre>return valor</pre><p>O <strong>return</strong> encerra a função e devolve um valor.</p>","exercise":"Crie uma função que receba preço e percentual de desconto e retorne o preço final.","id":"step17"},{"title":"18. Tratamento de erros","type":"practice","objective":"Evitar que o programa pare por erro de digitação.","code":"try:\n    numero = int(input(\"Digite um número inteiro: \"))\n    print(\"Dobro:\", numero * 2)\nexcept ValueError:\n    print(\"Erro: você não digitou um número inteiro válido.\")","output":"Python 3.x.x Shell\n>>> ================== RESTART ==================\nDigite um número inteiro: abc\nErro: você não digitou um número inteiro válido.\n>>>","work":"<h4>Conceitos</h4><p>Tratamento de erros permite lidar com situações inesperadas sem encerrar o programa de forma brusca.</p>\n<h4>Sintaxe trabalhada</h4><pre>try:\n    comandos\nexcept TipoDoErro:\n    comandos</pre><p><strong>ValueError</strong> ocorre, por exemplo, quando tentamos converter um texto inválido em número.</p>","exercise":"Leia a idade do usuário e trate o erro caso ele digite letras no lugar de número.","id":"step18"},{"id":"teoria-final","title":"19. Teoria final e boas práticas","type":"theory","objective":"Consolidar IDE, depuração, versionamento e boas práticas.","html":"\n<h3>IDLE como ambiente de programação</h3>\n<p>O <strong>IDLE</strong> é o ambiente simples que acompanha muitas instalações do Python. Ele possui o <strong>Shell</strong>, onde os resultados aparecem, e o <strong>editor</strong>, onde salvamos arquivos <code>.py</code>.</p>\n<div class=\"theory-grid\"><div class=\"theory-box\"><h4>Shell</h4><p>Área interativa para testar comandos e ver resultados.</p></div><div class=\"theory-box\"><h4>Editor</h4><p>Área para escrever programas completos e salvar arquivos Python.</p></div><div class=\"theory-box\"><h4>Run Module</h4><p>Executa o arquivo atual. Atalho comum: F5.</p></div></div>\n<h3>Depuração e erros</h3>\n<p>Depurar é procurar e corrigir erros. Erros comuns em iniciantes incluem falta de dois-pontos, indentação incorreta, nome de variável escrito errado e tentativa de converter texto inválido em número.</p>\n<div class=\"example-card\"><h4>Exemplos de erros comuns</h4><ul><li><strong>SyntaxError:</strong> erro de escrita da linguagem.</li><li><strong>IndentationError:</strong> erro nos espaços do bloco.</li><li><strong>NameError:</strong> uso de variável que não existe.</li><li><strong>ValueError:</strong> valor incompatível em uma conversão.</li></ul></div>\n<h3>Modularização de projetos</h3>\n<p>Modularizar é dividir o programa em partes menores. Em Python, isso começa com funções e pode evoluir para vários arquivos/módulos.</p>\n<h3>Versionamento</h3>\n<p>Versionamento é controlar alterações no código. O Git permite registrar versões com <strong>commits</strong>, recuperar versões anteriores e colaborar por repositórios remotos.</p>\n<h3>Boas práticas</h3>\n<ul class=\"clean-list\"><li>Use nomes claros para variáveis e funções.</li><li>Mantenha indentação correta.</li><li>Comente apenas o necessário.</li><li>Teste o programa com valores diferentes.</li><li>Prefira funções pequenas e objetivas.</li><li>Leia as mensagens de erro com calma.</li></ul>\n<h3>Programação em par</h3>\n<p>Dois alunos trabalham juntos: um escreve o código e o outro revisa, pensa nos testes e aponta melhorias. Depois, trocam os papéis.</p>\n<h3>Questionário de múltipla escolha</h3>\n<div class=\"quiz\"><ol>\n<li>Qual comando mostra algo na tela?<br><strong>A)</strong> input() &nbsp; <strong>B)</strong> print() &nbsp; <strong>C)</strong> int() &nbsp; <strong>D)</strong> def</li>\n<li>Qual comando lê dados do teclado?<br><strong>A)</strong> input() &nbsp; <strong>B)</strong> while &nbsp; <strong>C)</strong> return &nbsp; <strong>D)</strong> else</li>\n<li>O que a indentação define em Python?<br><strong>A)</strong> A cor do código &nbsp; <strong>B)</strong> O bloco de comandos &nbsp; <strong>C)</strong> O nome do arquivo &nbsp; <strong>D)</strong> A versão do Python</li>\n<li>Qual estrutura repete comandos enquanto uma condição for verdadeira?<br><strong>A)</strong> if &nbsp; <strong>B)</strong> while &nbsp; <strong>C)</strong> elif &nbsp; <strong>D)</strong> try</li>\n<li>Para que serve o Git?<br><strong>A)</strong> Editar imagens &nbsp; <strong>B)</strong> Controlar versões do código &nbsp; <strong>C)</strong> Criar planilhas &nbsp; <strong>D)</strong> Apagar erros automaticamente</li>\n</ol><p><strong>Gabarito:</strong> 1-B, 2-A, 3-B, 4-B, 5-B.</p></div>\n"},{"id":99,"title":"99. Exercícios","type":"theory","objective":"Praticar Python com 170 exercícios progressivos, organizados em sete níveis.","html":"\n<div class=\"theory-page exercises-99\">\n\n<div class=\"theory-hero\">\n<h3>99 — Exercícios de Lógica com Python</h3>\n<p>Esta página reúne exercícios para praticar lógica de programação. Não é necessário fazer tudo de uma vez: comece pelo nível em que você está, use as dicas quando travar e avance aos poucos.</p>\n</div>\n<div class=\"intro-grid\">\n<div class=\"intro-box\"><strong>Como estudar</strong><br/>Leia o enunciado com calma, identifique entradas, processamento e saída antes de programar.</div>\n<div class=\"intro-box\"><strong>Dicas</strong><br/>Passe o mouse ou toque sobre o selo 💡 Dica para receber uma orientação rápida sem ver a resposta pronta.</div>\n<div class=\"intro-box\"><strong>Exemplos resolvidos</strong><br/>Cada nível técnico começa com um modelo completo para ajudar a entender a estrutura do bloco.</div>\n</div>\n<section class=\"exercise-level\"><h3>Fundamentos</h3><p>Objetivo: praticar entrada e saída de dados, variáveis, atribuição, operadores aritméticos, conversões e cálculos simples.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Variáveis, entrada, saída e cálculo</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma loja deseja calcular o valor total de uma compra. O programa deve ler o preço unitário de um produto, a quantidade comprada e exibir o total a pagar.</p></div>\n<h4>Programa em Python</h4>\n<pre>preco = float(input(\"Digite o preço do produto: \"))\nquantidade = int(input(\"Digite a quantidade comprada: \"))\n\ntotal = preco * quantidade\n\nprint(f\"Total da compra: R$ {total:.2f}\")</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos variáveis ao receber os dados da compra.</li><li>Usamos input() e conversões para ler preço e quantidade.</li><li>Calculamos o valor total multiplicando o preço pela quantidade.</li><li>Exibimos o resultado com print().</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 1 — Saudação ao Usuário</strong>\n<p>Crie um programa que leia o nome de uma pessoa e exiba uma mensagem de boas-vindas contendo o nome informado.</p>\n<span class=\"badge\" title=\"Você precisa de uma variável do tipo caractere para guardar o nome.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 2 — Soma de Dois Valores</strong>\n<p>Desenvolva um programa que leia dois números inteiros, calcule a soma entre eles e mostre o resultado na tela.</p>\n<span class=\"badge\" title=\"Leia dois valores, some os dois e guarde o resultado em uma terceira variável.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 3 — Média de Três Notas</strong>\n<p>Uma escola precisa calcular a média de um aluno. Leia três notas, calcule a média aritmética e exiba o resultado final.</p>\n<span class=\"badge\" title=\"Some as três notas e divida o total por 3.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 4 — Dobro e Metade</strong>\n<p>Leia um número informado pelo usuário e mostre o dobro e a metade desse valor.</p>\n<span class=\"badge\" title=\"O dobro usa multiplicação. A metade usa divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 5 — Idade Futura</strong>\n<p>Leia a idade atual de uma pessoa e informe quantos anos ela terá daqui a 5 anos.</p>\n<span class=\"badge\" title=\"Some 5 ao valor digitado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 6 — Área de um Terreno</strong>\n<p>Um cliente deseja saber a área de um terreno retangular. Leia a largura e o comprimento do terreno e calcule a área total.</p>\n<span class=\"badge\" title=\"Área do retângulo = largura × comprimento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 7 — Área do Triângulo</strong>\n<p>Leia a base e a altura de um triângulo e calcule sua área.</p>\n<span class=\"badge\" title=\"Área do triângulo = base × altura ÷ 2.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 8 — Área do Círculo</strong>\n<p>Leia o raio de um círculo e calcule sua área.</p>\n<span class=\"badge\" title=\"Área do círculo = π × raio².\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 9 — Conversão de Temperatura</strong>\n<p>Leia uma temperatura em graus Celsius e converta para Fahrenheit.</p>\n<span class=\"badge\" title=\"Use a fórmula: Fahrenheit = Celsius × 1.8 + 32.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 10 — Reajuste Salarial</strong>\n<p>Uma empresa concedeu reajuste de 8% aos funcionários. Leia o salário atual e calcule o novo salário.</p>\n<span class=\"badge\" title=\"Calcule 8% do salário e some ao salário original.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 11 — Velocidade Média</strong>\n<p>Leia a distância percorrida por um veículo e o tempo gasto na viagem. Calcule e exiba a velocidade média.</p>\n<span class=\"badge\" title=\"Velocidade média = distância ÷ tempo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 12 — Total de Compra</strong>\n<p>Leia o nome de um produto, seu preço unitário e a quantidade comprada. Exiba o nome do produto e o valor total da compra.</p>\n<span class=\"badge\" title=\"Valor total = preço unitário × quantidade.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 13 — Conversão de Moeda</strong>\n<p>Leia um valor em reais e a cotação atual do dólar. Calcule quantos dólares podem ser comprados.</p>\n<span class=\"badge\" title=\"Divida o valor em reais pela cotação do dólar.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 14 — Média Bimestral</strong>\n<p>Um professor precisa calcular a média final de um aluno. Leia quatro notas bimestrais e exiba a média aritmética.</p>\n<span class=\"badge\" title=\"Some as quatro notas e divida por 4.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 15 — Dias em Horas</strong>\n<p>Leia uma quantidade de dias e converta esse valor para horas.</p>\n<span class=\"badge\" title=\"Cada dia possui 24 horas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 16 — Horas em Minutos</strong>\n<p>Leia uma quantidade de horas e converta para minutos.</p>\n<span class=\"badge\" title=\"Cada hora possui 60 minutos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 17 — Minutos em Segundos</strong>\n<p>Leia uma quantidade de minutos e converta para segundos.</p>\n<span class=\"badge\" title=\"Cada minuto possui 60 segundos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 18 — Antecessor e Sucessor</strong>\n<p>Leia um número inteiro e mostre seu antecessor e seu sucessor.</p>\n<span class=\"badge\" title=\"O antecessor é o número menos 1. O sucessor é o número mais 1.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 19 — Divisão de Conta</strong>\n<p>Três amigos foram a uma lanchonete e decidiram dividir a conta igualmente. Leia o valor total da conta e mostre quanto cada um deverá pagar.</p>\n<span class=\"badge\" title=\"Divida o valor total por 3.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 20 — Caixas e Garrafas</strong>\n<p>Uma distribuidora armazena refrigerantes em caixas com 12 garrafas. Leia a quantidade total de garrafas e informe:</p>\n<ul><li>Quantas caixas completas podem ser montadas.</li><li>Quantas garrafas sobram sem completar uma caixa.</li></ul>\n<span class=\"badge\" title=\"Utilize divisão inteira e resto da divisão.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Decisão</h3><p>Objetivo: praticar decisões simples, compostas, encadeadas e operadores booleanos.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Decisão com if e else</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja verificar se um aluno foi aprovado. O programa deve ler a nota final e mostrar se o aluno foi aprovado ou reprovado.</p></div>\n<h4>Programa em Python</h4>\n<pre>nota = float(input(\"Digite a nota final: \"))\n\nif nota &gt;= 6:\n    print(\"Aprovado\")\nelse:\n    print(\"Reprovado\")</pre>\n<h4>Explicação</h4>\n<ol><li>Declaramos a variável nota.</li><li>Lemos a nota digitada.</li><li>Usamos se/senao para separar os dois caminhos possíveis.</li><li>Se a nota for maior ou igual a 6, mostramos aprovado. Caso contrário, mostramos reprovado.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 21 — Aprovado ou Reprovado</strong>\n<p>Uma escola deseja automatizar a análise das notas dos alunos. Desenvolva um programa que leia a nota final de um estudante. Caso a nota seja maior ou igual a 6, exiba \"Aprovado\". Caso contrário, exiba \"Reprovado\".</p>\n<span class=\"badge\" title=\"Existem apenas duas possibilidades de resultado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 22 — Número Positivo ou Negativo</strong>\n<p>Leia um número informado pelo usuário e determine se ele é positivo, negativo ou igual a zero.</p>\n<span class=\"badge\" title=\"Observe que existem três possíveis classificações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 23 — Par ou Ímpar</strong>\n<p>Desenvolva um programa que leia um número inteiro e informe se ele é par ou ímpar.</p>\n<span class=\"badge\" title=\"Utilize o operador de resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 24 — Maioridade</strong>\n<p>Leia a idade de uma pessoa e informe se ela já atingiu a maioridade legal.</p>\n<span class=\"badge\" title=\"Compare a idade informada com 18 anos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 25 — Comparação entre Dois Valores</strong>\n<p>Leia dois números inteiros e informe qual deles possui o maior valor. Caso sejam iguais, informe essa situação ao usuário.</p>\n<span class=\"badge\" title=\"Nem sempre um valor será maior que o outro.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 26 — Validação de Nota</strong>\n<p>Leia a nota de um aluno. Caso a nota esteja fora do intervalo de 0 a 10, exiba a mensagem \"Nota inválida\". Caso contrário, exiba a nota informada.</p>\n<span class=\"badge\" title=\"Primeiro valide os dados recebidos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 27 — Classificação de Desempenho</strong>\n<p>Leia a nota final de um estudante e classifique: aprovado se for igual ou superior a 7; recuperação se estiver entre 5 e 6,9; reprovado se for inferior a 5.</p>\n<span class=\"badge\" title=\"Existem três faixas diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 28 — Faixa Etária</strong>\n<p>Leia a idade de uma pessoa e classifique como criança, adolescente, adulto ou idoso, usando faixas de idade coerentes para cada categoria.</p>\n<span class=\"badge\" title=\"Será necessário trabalhar com intervalos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 29 — Saudação por Horário</strong>\n<p>Leia uma hora inteira entre 0 e 23. Exiba bom dia, boa tarde ou boa noite de acordo com o horário. Caso o valor esteja fora do intervalo, informe que a hora é inválida.</p>\n<span class=\"badge\" title=\"Primeiro verifique se a hora é válida.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 30 — Sistema de Login</strong>\n<p>Desenvolva um programa que leia um nome de usuário e uma senha. Considere usuário correto admin e senha correta 1234. Informe se o acesso foi autorizado ou negado.</p>\n<span class=\"badge\" title=\"As duas condições precisam ser verdadeiras.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 31 — Código de Região</strong>\n<p>Uma empresa utiliza códigos para regiões: 1 Norte, 2 Sul, 3 Leste e 4 Oeste. Leia um código e informe a região correspondente. Caso o código não exista, informe \"Região não cadastrada\".</p>\n<span class=\"badge\" title=\"Compare o valor digitado com várias opções.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 32 — Controle de Velocidade</strong>\n<p>Leia a velocidade registrada por um veículo. Classifique como dentro do limite até 80 km/h, infração leve de 81 a 100 km/h e infração grave acima de 100 km/h.</p>\n<span class=\"badge\" title=\"Analise intervalos de valores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 33 — Intervalo Numérico</strong>\n<p>Leia um número inteiro e informe se ele pertence ao intervalo entre 10 e 20, inclusive.</p>\n<span class=\"badge\" title=\"Será necessário utilizar duas comparações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 34 — Múltiplo de 3 e de 5</strong>\n<p>Leia um número inteiro e informe se ele é múltiplo de 3 e de 5 ao mesmo tempo.</p>\n<span class=\"badge\" title=\"Duas condições precisam ser satisfeitas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 35 — Verificação de Triângulo</strong>\n<p>Leia três valores que representam lados de um possível triângulo. Informe se esses valores podem formar um triângulo.</p>\n<span class=\"badge\" title=\"Nem toda combinação de três lados forma um triângulo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 36 — Classificação de Triângulo</strong>\n<p>Após verificar que três lados formam um triângulo, classifique-o em equilátero, isósceles ou escaleno.</p>\n<span class=\"badge\" title=\"Observe quais lados possuem medidas iguais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 37 — Empréstimo Bancário</strong>\n<p>Um banco analisa pedidos de crédito. Leia o salário do cliente e o valor solicitado. O empréstimo será aprovado apenas se o valor solicitado não ultrapassar quatro vezes o salário informado.</p>\n<span class=\"badge\" title=\"Compare o valor solicitado com um limite calculado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 38 — Reajuste Salarial por Faixa</strong>\n<p>Uma empresa definiu reajustes por faixa: até R$ 2.000 aumento de 12%; de R$ 2.000,01 até R$ 4.000 aumento de 8%; acima de R$ 4.000 aumento de 5%. Leia o salário atual e exiba o novo salário.</p>\n<span class=\"badge\" title=\"Cada faixa possui uma regra diferente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 39 — Cálculo de IMC</strong>\n<p>Leia peso e altura de uma pessoa. Calcule o IMC e classifique como abaixo do peso, peso normal, sobrepeso ou obesidade.</p>\n<span class=\"badge\" title=\"Primeiro faça o cálculo. Depois classifique.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 40 — Ordenação de Três Valores</strong>\n<p>Leia três números inteiros e exiba os valores em ordem crescente.</p>\n<span class=\"badge\" title=\"Pense em como descobrir qual é o menor, o intermediário e o maior valor.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Repetição</h3><p>Objetivo: praticar contadores, acumuladores, médias, estatísticas e problemas com repetição.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Repetição com for</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja exibir os números de chamada dos alunos de uma turma. Desenvolva um programa que mostre os números de 1 até 10 na tela.</p></div>\n<h4>Programa em Python</h4>\n<pre>for contador in range(1, 11):\n    print(contador)</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma variável contador.</li><li>O laço começa em 1 e termina em 10.</li><li>A cada repetição, o valor do contador é exibido.</li><li>Quando o contador passa do limite, a repetição termina.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 41 — Contagem Crescente</strong>\n<p>Desenvolva um programa que exiba na tela todos os números inteiros de 1 até 20.</p>\n<span class=\"badge\" title=\"Você não precisa criar vinte comandos de escrita.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 42 — Contagem Regressiva</strong>\n<p>Crie um programa que exiba os números de 20 até 1 em ordem decrescente.</p>\n<span class=\"badge\" title=\"O contador deverá diminuir a cada repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 43 — Números Pares</strong>\n<p>Desenvolva um programa que exiba todos os números pares entre 2 e 50.</p>\n<span class=\"badge\" title=\"Existe mais de uma forma de resolver esse problema.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 44 — Números Ímpares</strong>\n<p>Exiba todos os números ímpares entre 1 e 49.</p>\n<span class=\"badge\" title=\"Observe o padrão de crescimento da sequência.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 45 — Contando de Cinco em Cinco</strong>\n<p>Mostre na tela os números de 0 até 100, avançando de cinco em cinco.</p>\n<span class=\"badge\" title=\"Nem todo laço precisa incrementar de um em um.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 46 — Contagem Regressiva de Lançamento</strong>\n<p>Desenvolva um programa que exiba uma contagem de 10 até 1 e, ao final, mostre a mensagem \"Lançamento!\".</p>\n<span class=\"badge\" title=\"Primeiro faça a contagem. Depois exiba a mensagem final.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 47 — Soma de 1 até 100</strong>\n<p>Calcule a soma de todos os números inteiros entre 1 e 100 e exiba o resultado final.</p>\n<span class=\"badge\" title=\"Você precisará de uma variável acumuladora.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 48 — Soma dos Números Pares</strong>\n<p>Calcule a soma de todos os números pares entre 2 e 100.</p>\n<span class=\"badge\" title=\"Nem todos os números devem participar da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 49 — Tabuada</strong>\n<p>Leia um número inteiro informado pelo usuário e exiba sua tabuada de multiplicação de 1 até 10.</p>\n<span class=\"badge\" title=\"O valor digitado será multiplicado várias vezes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 50 — Dez Números e uma Soma</strong>\n<p>Solicite ao usuário dez números inteiros. Ao final, exiba a soma de todos os valores digitados.</p>\n<span class=\"badge\" title=\"A cada leitura, atualize o total acumulado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 51 — Média de uma Turma</strong>\n<p>Um professor deseja calcular a média de uma turma. Desenvolva um programa que leia as notas de 10 alunos e, ao final, exiba a média da turma.</p>\n<span class=\"badge\" title=\"Você precisará acumular todas as notas antes de calcular a média.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 52 — Contando Valores Positivos</strong>\n<p>Solicite ao usuário 15 números inteiros. Ao final, informe quantos deles são positivos.</p>\n<span class=\"badge\" title=\"Crie um contador que aumente apenas quando a condição for verdadeira.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 53 — Contando Valores Negativos</strong>\n<p>Leia 15 números inteiros e informe quantos valores negativos foram digitados.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 54 — Quantidade de Números Pares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são pares.</p>\n<span class=\"badge\" title=\"Utilize o operador de resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 55 — Quantidade de Números Ímpares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são ímpares.</p>\n<span class=\"badge\" title=\"Nem todos os números digitados devem ser contabilizados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 56 — Maior Valor Informado</strong>\n<p>Solicite ao usuário 10 números inteiros. Ao final, exiba qual foi o maior valor digitado.</p>\n<span class=\"badge\" title=\"Você precisará guardar temporariamente o maior valor encontrado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 57 — Menor Valor Informado</strong>\n<p>Leia 10 números inteiros e informe qual foi o menor valor digitado.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 58 — Maior e Menor Valor</strong>\n<p>Leia 15 números inteiros e exiba, ao final, o maior e o menor valor encontrados.</p>\n<span class=\"badge\" title=\"Você precisará acompanhar duas informações durante o processamento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 59 — Média de Alturas</strong>\n<p>Uma academia deseja calcular a altura média de seus alunos. Leia a altura de 20 pessoas e exiba a média ao final.</p>\n<span class=\"badge\" title=\"Some todas as alturas antes de dividir.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 60 — Média de Idades</strong>\n<p>Leia a idade de 25 pessoas e calcule a média de idade do grupo.</p>\n<span class=\"badge\" title=\"O raciocínio é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 61 — Aprovados na Turma</strong>\n<p>Leia as notas de 20 alunos. Considere aprovado quem obtiver nota maior ou igual a 6. Ao final, informe quantos alunos foram aprovados.</p>\n<span class=\"badge\" title=\"Misture repetição com decisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 62 — Reprovados na Turma</strong>\n<p>Leia as notas de 20 alunos e informe quantos ficaram reprovados.</p>\n<span class=\"badge\" title=\"Você pode reutilizar a lógica do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 63 — Pesquisa de Idades</strong>\n<p>Uma empresa realizou uma pesquisa com 30 pessoas. Leia as idades e informe a maior idade, a menor idade e a média das idades.</p>\n<span class=\"badge\" title=\"Será necessário combinar acumuladores e comparações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 64 — Pesquisa de Alturas</strong>\n<p>Leia a altura de 20 pessoas e informe a maior altura, a menor altura e a altura média.</p>\n<span class=\"badge\" title=\"Guarde os extremos encontrados durante a leitura.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 65 — Soma dos Múltiplos de 3</strong>\n<p>Calcule a soma de todos os múltiplos de 3 existentes entre 1 e 100.</p>\n<span class=\"badge\" title=\"Nem todos os números participam da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 66 — Soma dos Múltiplos de 5</strong>\n<p>Calcule a soma de todos os múltiplos de 5 existentes entre 1 e 100.</p>\n<span class=\"badge\" title=\"Primeiro identifique quais valores atendem à condição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 67 — Quantos Estão no Intervalo</strong>\n<p>Leia 20 números inteiros e informe quantos deles estão entre 10 e 50, inclusive.</p>\n<span class=\"badge\" title=\"Será necessário usar uma condição dentro do laço.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 68 — Tabuadas de 1 a 10</strong>\n<p>Exiba as tabuadas completas dos números de 1 até 10.</p>\n<span class=\"badge\" title=\"Pense em uma repetição dentro de outra repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 69 — Fatorial</strong>\n<p>Leia um número inteiro positivo e calcule seu fatorial.</p>\n<span class=\"badge\" title=\"Você precisará multiplicar vários valores sucessivamente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 70 — Número Primo</strong>\n<p>Leia um número inteiro positivo e informe se ele é primo.</p>\n<span class=\"badge\" title=\"Verifique quantos divisores o número possui.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 71 — Divisores de um Número</strong>\n<p>Desenvolva um programa que leia um número inteiro positivo e exiba todos os seus divisores.</p>\n<span class=\"badge\" title=\"Verifique quais números dividem o valor informado sem deixar resto.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 72 — Soma dos Divisores</strong>\n<p>Leia um número inteiro positivo e calcule a soma de todos os seus divisores.</p>\n<span class=\"badge\" title=\"Primeiro descubra os divisores. Depois some os valores encontrados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 73 — Sequência de Fibonacci</strong>\n<p>Exiba os 15 primeiros números da sequência de Fibonacci, começando em 0 e 1.</p>\n<span class=\"badge\" title=\"Cada novo termo é obtido pela soma dos dois anteriores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 74 — Pesquisa de Satisfação</strong>\n<p>Uma empresa realizou uma pesquisa com 20 clientes. Cada cliente deve informar uma nota de 1 a 5. Ao final, exiba a média, a maior nota e a menor nota.</p>\n<span class=\"badge\" title=\"Você precisará acumular valores e comparar resultados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 75 — Pesquisa Eleitoral Simplificada</strong>\n<p>Durante uma pesquisa, 30 pessoas devem escolher entre três candidatos. Ao final, informe quantos votos cada candidato recebeu.</p>\n<span class=\"badge\" title=\"Crie um contador para cada opção.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 76 — Controle de Vendas</strong>\n<p>Uma loja deseja registrar o valor de 15 vendas realizadas durante o dia. Ao final, exiba o valor total vendido, a média das vendas e a maior venda realizada.</p>\n<span class=\"badge\" title=\"Nem todas as informações são calculadas da mesma forma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 77 — Estatística da Turma</strong>\n<p>Leia as notas de 25 alunos. Ao final, informe a média da turma, a quantidade de aprovados e a quantidade de reprovados.</p>\n<span class=\"badge\" title=\"Misture repetição, acumuladores e decisões.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 78 — Contagem de Faixas Etárias</strong>\n<p>Leia a idade de 20 pessoas. Ao final, informe quantas pertencem aos grupos criança, adolescente, adulto e idoso.</p>\n<span class=\"badge\" title=\"Cada faixa precisa de seu próprio contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 79 — Maior Sequência</strong>\n<p>Leia 15 números inteiros e determine qual foi o maior valor informado. Além disso, informe em qual posição ele foi digitado.</p>\n<span class=\"badge\" title=\"Você precisará acompanhar o valor e sua posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 80 — Controle de Estoque</strong>\n<p>Uma loja possui 10 produtos cadastrados. Para cada produto, informe a quantidade atual em estoque. Ao final, exiba o total de itens, o maior estoque e o menor estoque.</p>\n<span class=\"badge\" title=\"Guarde os extremos encontrados durante a leitura.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 81 — Média até Valor de Parada</strong>\n<p>Leia vários números até que seja digitado o valor 0. Ao final, exiba a média dos números digitados.</p>\n<span class=\"badge\" title=\"O valor que encerra a leitura não participa do cálculo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 82 — Soma até Valor de Parada</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, exiba a soma de todos os valores informados.</p>\n<span class=\"badge\" title=\"Esse exercício é semelhante ao anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 83 — Quantidade de Entradas</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe quantos números foram digitados.</p>\n<span class=\"badge\" title=\"Use um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 84 — Maior Valor até Encerramento</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe qual foi o maior número digitado.</p>\n<span class=\"badge\" title=\"O valor de encerramento não deve ser considerado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 85 — Menor Valor até Encerramento</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe qual foi o menor número digitado.</p>\n<span class=\"badge\" title=\"Pense em como inicializar a variável que armazenará o menor valor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 86 — Soma dos Pares Informados</strong>\n<p>Leia 20 números inteiros e calcule a soma apenas dos números pares.</p>\n<span class=\"badge\" title=\"Nem todos os valores participam da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 87 — Soma dos Ímpares Informados</strong>\n<p>Leia 20 números inteiros e calcule a soma apenas dos números ímpares.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 88 — Média dos Valores Positivos</strong>\n<p>Leia 20 números inteiros e calcule a média apenas dos valores positivos.</p>\n<span class=\"badge\" title=\"Você precisará controlar quantidade e soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 89 — Classificação de Temperaturas</strong>\n<p>Leia a temperatura registrada durante 30 dias. Ao final, informe maior temperatura, menor temperatura e temperatura média.</p>\n<span class=\"badge\" title=\"O raciocínio é semelhante ao das pesquisas anteriores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 90 — Simulação de Caixa</strong>\n<p>Um caixa registrou 20 compras durante o dia. Leia o valor de cada compra e informe o faturamento total, a média das compras e a maior compra realizada.</p>\n<span class=\"badge\" title=\"Este exercício reúne vários conceitos já praticados neste nível.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Listas (vetores)</h3><p>Objetivo: armazenar vários valores em uma única estrutura e percorrer suas posições.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Lista (vetor) de notas</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja armazenar as notas de 5 alunos para exibi-las depois. Desenvolva um programa que leia as cinco notas, armazene-as em um lista (vetor) e mostre todas as notas digitadas.</p></div>\n<h4>Programa em Python</h4>\n<pre>notas = []\n\nfor i in range(5):\n    nota = float(input(f\"Digite a {i + 1}ª nota: \"))\n    notas.append(nota)\n\nprint(\"Notas cadastradas:\")\nfor nota in notas:\n    print(nota)</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos um lista (vetor) com 5 posições.</li><li>O primeiro laço lê e guarda cada nota.</li><li>Cada nota ocupa uma posição diferente do lista (vetor).</li><li>O segundo laço percorre o lista (vetor) para exibir os valores armazenados.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 91 — Cadastro de Valores</strong>\n<p>Desenvolva um programa que leia 10 números inteiros e os armazene em um lista (vetor). Após a leitura, exiba todos os valores na mesma ordem em que foram digitados.</p>\n<span class=\"badge\" title=\"Primeiro armazene. Depois percorra o vetor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 92 — Ordem Inversa</strong>\n<p>Leia 10 números inteiros e armazene-os em um lista (vetor). Ao final, exiba os valores na ordem inversa da digitação.</p>\n<span class=\"badge\" title=\"Percorra o vetor do fim para o início.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 93 — Maior Elemento</strong>\n<p>Leia 15 números inteiros e armazene-os em um lista (vetor). Ao final, informe qual é o maior valor armazenado.</p>\n<span class=\"badge\" title=\"Compare cada elemento com o maior encontrado até o momento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 94 — Menor Elemento</strong>\n<p>Leia 15 números inteiros e informe qual é o menor valor armazenado no lista (vetor).</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 95 — Média dos Elementos</strong>\n<p>Leia 20 números reais e armazene-os em um lista (vetor). Calcule e exiba a média dos valores armazenados.</p>\n<span class=\"badge\" title=\"Some todos os elementos antes de calcular a média.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 96 — Quantidade de Pares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são pares.</p>\n<span class=\"badge\" title=\"Percorra o vetor verificando cada elemento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 97 — Quantidade de Ímpares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são ímpares.</p>\n<span class=\"badge\" title=\"A solução é muito parecida com a do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 98 — Procurando um Valor</strong>\n<p>Leia 10 números inteiros e armazene-os em um lista (vetor). Em seguida, solicite um número ao usuário e informe se ele está presente no lista (vetor).</p>\n<span class=\"badge\" title=\"Será necessário percorrer todas as posições.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 99 — Localizando a Posição</strong>\n<p>Leia 10 números inteiros. Depois, solicite um valor para pesquisa. Caso ele exista no lista (vetor), informe em qual posição foi encontrado.</p>\n<span class=\"badge\" title=\"Guarde também o índice da posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 100 — Soma dos Elementos</strong>\n<p>Leia 15 números inteiros e calcule a soma de todos os valores armazenados no lista (vetor).</p>\n<span class=\"badge\" title=\"Use uma variável acumuladora.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 101 — Substituindo Negativos</strong>\n<p>Leia 15 números inteiros. Sempre que um valor negativo for encontrado, substitua-o por zero. Ao final, exiba o lista (vetor) atualizado.</p>\n<span class=\"badge\" title=\"Você pode alterar o próprio vetor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 102 — Contando Ocorrências</strong>\n<p>Leia 20 números inteiros. Em seguida, solicite um valor para pesquisa e informe quantas vezes ele aparece no lista (vetor).</p>\n<span class=\"badge\" title=\"Cada ocorrência encontrada aumenta um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 103 — Lista (vetor) Copiado</strong>\n<p>Leia 10 números inteiros em um lista (vetor) A. Copie todos os valores para um lista (vetor) B e exiba os dois listas (lista (vetor)es).</p>\n<span class=\"badge\" title=\"Percorra ambos utilizando o mesmo índice.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 104 — Comparação de Lista (vetor)es</strong>\n<p>Leia dois listas (lista (vetor)es) com 10 números inteiros cada. Informe quantas posições possuem valores iguais.</p>\n<span class=\"badge\" title=\"Compare posição por posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 105 — Soma de Lista (vetor)es</strong>\n<p>Leia dois listas (lista (vetor)es) com 10 números inteiros cada. Crie um terceiro lista (vetor) contendo a soma dos elementos correspondentes.</p>\n<span class=\"badge\" title=\"A posição do vetor resultado depende da mesma posição dos dois vetores originais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 106 — Junção de Lista (vetor)es</strong>\n<p>Leia dois listas (lista (vetor)es) contendo 5 números inteiros cada. Crie um terceiro lista (vetor) contendo todos os elementos dos dois listas (lista (vetor)es).</p>\n<span class=\"badge\" title=\"O novo vetor terá mais posições do que os vetores originais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 107 — Ranking de Notas</strong>\n<p>Leia as notas de 10 alunos e determine a maior nota, a menor nota e a média da turma.</p>\n<span class=\"badge\" title=\"Você já resolveu problemas parecidos usando repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 108 — Números Acima da Média</strong>\n<p>Leia 15 números reais. Calcule a média e informe quantos valores estão acima dela.</p>\n<span class=\"badge\" title=\"Talvez seja necessário percorrer o vetor mais de uma vez.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 109 — Valores em Posições Pares</strong>\n<p>Leia 20 números inteiros e exiba apenas os elementos armazenados em posições pares do lista (vetor).</p>\n<span class=\"badge\" title=\"Observe o índice e não o valor armazenado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 110 — Valores em Posições Ímpares</strong>\n<p>Leia 20 números inteiros e exiba apenas os elementos armazenados em posições ímpares.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Listas de listas (matrizes)</h3><p>Objetivo: usar linhas e colunas para representar tabelas, boletins, vendas e ambientes físicos.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Lista de listas (matriz) de notas</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja armazenar as notas de 3 alunos em 3 bimestres. Desenvolva um programa que leia essas notas em uma lista de listas (matriz) 3x3 e depois exiba todos os valores armazenados.</p></div>\n<h4>Programa em Python</h4>\n<pre>notas = []\n\nfor linha in range(3):\n    nova_linha = []\n    for coluna in range(3):\n        nota = float(input(f\"Nota [{linha + 1}][{coluna + 1}]: \"))\n        nova_linha.append(nota)\n    notas.append(nova_linha)\n\nfor linha in notas:\n    for nota in linha:\n        print(nota, end=\" \")\n    print()</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma lista de listas (matriz) 3x3.</li><li>Cada posição é acessada por linha e coluna.</li><li>Usamos dois laços: um para linhas e outro para colunas.</li><li>Depois percorremos novamente a lista de listas (matriz) para exibir os valores.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 111 — Cadastro em Lista de listas (matriz)</strong>\n<p>Leia 9 números inteiros e armazene-os em uma lista de listas (matriz) 3x3. Ao final, exiba todos os valores organizados em formato de tabela.</p>\n<span class=\"badge\" title=\"Você precisará percorrer linhas e colunas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 112 — Soma de Todos os Elementos</strong>\n<p>Leia os valores de uma lista de listas (matriz) 3x3 e calcule a soma de todos os elementos armazenados.</p>\n<span class=\"badge\" title=\"Some cada elemento à medida que ele for percorrido.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 113 — Média da Lista de listas (matriz)</strong>\n<p>Leia uma lista de listas (matriz) 3x3 contendo números reais. Calcule e exiba a média de todos os valores armazenados.</p>\n<span class=\"badge\" title=\"Primeiro obtenha a soma total.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 114 — Maior Elemento</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e informe qual é o maior valor armazenado.</p>\n<span class=\"badge\" title=\"Compare cada elemento com o maior encontrado até o momento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 115 — Menor Elemento</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e informe qual é o menor valor armazenado.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 116 — Quantidade de Números Pares</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e informe quantos elementos possuem valor par.</p>\n<span class=\"badge\" title=\"Verifique cada elemento individualmente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 117 — Quantidade de Números Ímpares</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e informe quantos elementos possuem valor ímpar.</p>\n<span class=\"badge\" title=\"Utilize a mesma estratégia do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 118 — Soma da Linha Informada</strong>\n<p>Leia uma lista de listas (matriz) 4x4. Em seguida, solicite ao usuário o número de uma linha e calcule a soma dos elementos dessa linha.</p>\n<span class=\"badge\" title=\"Nem todas as linhas precisam ser processadas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 119 — Soma da Coluna Informada</strong>\n<p>Leia uma lista de listas (matriz) 4x4. Solicite ao usuário o número de uma coluna e calcule a soma dos valores dessa coluna.</p>\n<span class=\"badge\" title=\"Observe qual índice permanece fixo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 120 — Soma da Diagonal Principal</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e calcule a soma dos elementos da diagonal principal.</p>\n<span class=\"badge\" title=\"Na diagonal principal, linha e coluna possuem o mesmo índice.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 121 — Soma da Diagonal Secundária</strong>\n<p>Leia uma lista de listas (matriz) 4x4 e calcule a soma dos elementos da diagonal secundária.</p>\n<span class=\"badge\" title=\"Observe a posição dos elementos que formam a diagonal oposta.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 122 — Boletim Escolar</strong>\n<p>Uma escola deseja armazenar as notas de 5 alunos em 4 bimestres. Use uma lista de listas (matriz) para armazenar os dados e calcule a média de cada aluno e a média geral da turma.</p>\n<span class=\"badge\" title=\"Cada linha pode representar um aluno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 123 — Controle de Vendas</strong>\n<p>Uma loja registrou as vendas de 4 vendedores durante 5 dias. Armazene os valores em uma lista de listas (matriz) e informe o total vendido por vendedor e o total vendido em cada dia.</p>\n<span class=\"badge\" title=\"Linhas e colunas representam informações diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 124 — Ocupação de Estacionamento</strong>\n<p>Um estacionamento possui 5 fileiras com 6 vagas cada. Use uma lista de listas (matriz) para registrar 0 para vaga livre e 1 para vaga ocupada. Ao final, informe quantas vagas estão ocupadas.</p>\n<span class=\"badge\" title=\"Conte apenas os elementos com valor 1.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 125 — Sala de Aula</strong>\n<p>Uma sala possui 5 fileiras e 5 colunas de carteiras. Use uma lista de listas (matriz) para representar 0 para carteira vazia e 1 para carteira ocupada. Informe a quantidade de carteiras ocupadas e livres.</p>\n<span class=\"badge\" title=\"Toda matriz pode representar um ambiente físico.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 126 — Temperaturas da Semana</strong>\n<p>Uma estação meteorológica registrou temperaturas durante 4 semanas e 7 dias. Armazene os valores em uma lista de listas (matriz) e informe maior temperatura, menor temperatura e média.</p>\n<span class=\"badge\" title=\"A matriz funciona como uma tabela.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 127 — Lista de listas (matriz) Transposta</strong>\n<p>Leia uma lista de listas (matriz) 3x3 e exiba sua lista de listas (matriz) transposta.</p>\n<span class=\"badge\" title=\"Linhas se transformam em colunas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 128 — Soma de Lista de listas (matriz)es</strong>\n<p>Leia duas listas de listas (lista de listas (matriz)es) 3x3 contendo números inteiros. Crie uma terceira lista de listas (matriz) contendo a soma dos elementos correspondentes.</p>\n<span class=\"badge\" title=\"Cada posição depende das posições equivalentes das duas matrizes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 129 — Diferença de Lista de listas (matriz)es</strong>\n<p>Leia duas listas de listas (lista de listas (matriz)es) 3x3 e gere uma terceira lista de listas (matriz) contendo a diferença entre os elementos correspondentes.</p>\n<span class=\"badge\" title=\"A lógica é semelhante à soma de matrizes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 130 — Pesquisa de Notas</strong>\n<p>Uma escola armazenou as notas de 10 alunos em 4 avaliações. Use uma lista de listas (matriz) para informar a média de cada aluno, maior nota, menor nota e média geral da turma.</p>\n<span class=\"badge\" title=\"Este exercício reúne praticamente todos os conceitos trabalhados neste nível.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Funções</h3><p>Objetivo: dividir programas em partes menores, reutilizar código e organizar soluções.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Função sem retorno</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja exibir uma mensagem de boas-vindas várias vezes durante a execução do programa. Desenvolva um programa utilizando um função sem retorno para exibir a mensagem.</p></div>\n<h4>Programa em Python</h4>\n<pre>def enviar_mensagem():\n    print(\"Bem-vindo ao Mundo bit Byte!\")\n\n\nenviar_mensagem()\nenviar_mensagem()\nenviar_mensagem()</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos um função sem retorno chamado aviso.</li><li>O função sem retorno possui uma tarefa específica.</li><li>Sempre que o função sem retorno é chamado, um aviso é exibido.</li><li>Isso evita repetir o mesmo comando várias vezes no programa principal.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 131 — Função sem retorno de Saudação</strong>\n<p>Crie um função sem retorno que exiba uma mensagem de boas-vindas ao usuário. No programa principal, chame esse função sem retorno três vezes.</p>\n<span class=\"badge\" title=\"Um função sem retorno pode ser executado quantas vezes forem necessárias.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 132 — Função sem retorno para Linha Decorativa</strong>\n<p>Crie um função sem retorno responsável por exibir uma linha contendo 40 caracteres \"-\". Chame o função sem retorno antes e depois de uma mensagem principal.</p>\n<span class=\"badge\" title=\"O função sem retorno deve ter apenas uma responsabilidade.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 133 — Função sem retorno para Tabuada</strong>\n<p>Crie um função sem retorno que receba um número inteiro e exiba sua tabuada de 1 até 10.</p>\n<span class=\"badge\" title=\"Funções sem retorno podem receber informações através de parâmetros.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 134 — Função sem retorno para Média</strong>\n<p>Crie um função sem retorno que receba três notas e exiba a média calculada.</p>\n<span class=\"badge\" title=\"Os valores podem ser enviados ao função sem retorno quando ele for chamado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 135 — Função sem retorno para Aprovação</strong>\n<p>Crie um função sem retorno que receba uma nota e exiba aprovado ou reprovado conforme o valor recebido.</p>\n<span class=\"badge\" title=\"Você precisará utilizar uma estrutura de decisão dentro do função sem retorno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 136 — Função de Soma</strong>\n<p>Crie uma função que receba dois números inteiros e retorne a soma deles. No programa principal, exiba o resultado retornado.</p>\n<span class=\"badge\" title=\"A diferença principal é que a função devolve um valor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 137 — Função para Média</strong>\n<p>Crie uma função que receba três notas e retorne a média aritmética.</p>\n<span class=\"badge\" title=\"O cálculo será feito dentro da função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 138 — Função Par ou Ímpar</strong>\n<p>Crie uma função que receba um número inteiro e retorne True se o número for par e False se for ímpar.</p>\n<span class=\"badge\" title=\"O operador de resto da divisão será útil.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 139 — Função para Maior Valor</strong>\n<p>Crie uma função que receba dois números e retorne o maior deles.</p>\n<span class=\"badge\" title=\"Use uma estrutura de decisão antes do retorno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 140 — Função para Menor Valor</strong>\n<p>Crie uma função que receba dois números e retorne o menor deles.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 141 — Função de Potência</strong>\n<p>Crie uma função que receba uma base e um expoente inteiro positivo e retorne o resultado da potência.</p>\n<span class=\"badge\" title=\"Você pode utilizar repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 142 — Função de IMC</strong>\n<p>Crie uma função que receba peso e altura e retorne o valor do IMC calculado.</p>\n<span class=\"badge\" title=\"A função deve apenas calcular e retornar o resultado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 143 — Função de Fatorial</strong>\n<p>Crie uma função que receba um número inteiro positivo e retorne seu fatorial.</p>\n<span class=\"badge\" title=\"Utilize um acumulador para realizar as multiplicações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 144 — Função para Número Primo</strong>\n<p>Crie uma função que receba um número inteiro positivo e informe se ele é primo.</p>\n<span class=\"badge\" title=\"A função deve analisar os divisores do número.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 145 — Função sem retorno para Cadastro de Aluno</strong>\n<p>Crie um função sem retorno que receba nome, nota 1 e nota 2. O função sem retorno deverá calcular a média e exibir um relatório simples do aluno.</p>\n<span class=\"badge\" title=\"Agrupe tarefas relacionadas em um único função sem retorno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 146 — Função para Desconto</strong>\n<p>Crie uma função que receba o valor de um produto e um percentual de desconto e retorne o valor final.</p>\n<span class=\"badge\" title=\"A função deve devolver apenas o valor calculado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 147 — Função para Conversão de Temperatura</strong>\n<p>Crie uma função que receba uma temperatura em Celsius e retorne o valor correspondente em Fahrenheit.</p>\n<span class=\"badge\" title=\"A fórmula deve ficar dentro da função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 148 — Função sem retorno para Relatório de Vendas</strong>\n<p>Crie um função sem retorno que receba nome do vendedor, quantidade vendida e valor total vendido. O função sem retorno deverá exibir um relatório organizado na tela.</p>\n<span class=\"badge\" title=\"O função sem retorno será responsável apenas pela apresentação dos dados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 149 — Função para Verificar Aprovação</strong>\n<p>Crie uma função que receba a média de um aluno e retorne True para aprovado e False para reprovado. Considere média mínima igual a 6.</p>\n<span class=\"badge\" title=\"O retorno da função pode ser lógico.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 150 — Sistema Modularizado</strong>\n<p>Desenvolva um programa que utilize pelo menos duas funções e dois funções sem retorno. O programa deve ler dados de um aluno, calcular sua média e exibir um relatório final.</p>\n<span class=\"badge\" title=\"Divida o problema em partes menores e reutilizáveis.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3> Desafios</h3><p>Objetivo: integrar variáveis, decisões, repetições, listas (lista (vetor)es), listas de listas (lista de listas (matriz)es), funções sem retorno e funções com retorno em problemas maiores.</p>\n<div class=\"question exercise-item\">\n<strong>Exercício 151 — Boletim Escolar Completo</strong>\n<p>Desenvolva um programa para registrar as notas de uma turma. O programa deve ler o nome de 10 alunos e suas quatro notas bimestrais. Ao final, exiba a média de cada aluno e informe se ele foi aprovado ou reprovado.</p>\n<span class=\"badge\" title=\"Use vetores para nomes e médias. A aprovação depende de uma decisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 152 — Controle de Estoque</strong>\n<p>Uma loja deseja controlar 10 produtos. Para cada produto, leia o nome, a quantidade em estoque e o preço unitário. Ao final, informe o valor total armazenado em estoque e qual produto possui maior quantidade.</p>\n<span class=\"badge\" title=\"Cada produto possui mais de uma informação.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 153 — Sistema de Biblioteca</strong>\n<p>Crie um programa para registrar 10 livros de uma biblioteca. Para cada livro, leia título, autor e quantidade disponível. Ao final, permita pesquisar um título e informe se ele está cadastrado.</p>\n<span class=\"badge\" title=\"Será necessário percorrer os registros armazenados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 154 — Controle de Vendas</strong>\n<p>Uma loja registrou as vendas de 5 vendedores durante 4 semanas. Armazene os valores em uma lista de listas (matriz) e informe o total vendido por cada vendedor e o total geral da loja.</p>\n<span class=\"badge\" title=\"Cada linha pode representar um vendedor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 155 — Caixa Eletrônico Simples</strong>\n<p>Desenvolva um programa que leia um valor inteiro para saque e informe quantas notas de 100, 50, 20, 10 e 5 serão necessárias.</p>\n<span class=\"badge\" title=\"Use divisão inteira e resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 156 — Pesquisa de Satisfação</strong>\n<p>Uma empresa entrevistou 30 clientes. Cada cliente informou uma nota de 1 a 5. Ao final, exiba a média das avaliações e a quantidade de votos em cada nota.</p>\n<span class=\"badge\" title=\"Crie contadores separados para cada nota.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 157 — Campeonato Escolar</strong>\n<p>Leia o nome de 6 equipes e a pontuação de cada uma. Ao final, informe a equipe campeã, a menor pontuação e a média de pontos do campeonato.</p>\n<span class=\"badge\" title=\"Compare os pontos enquanto percorre os dados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 158 — Agenda de Contatos</strong>\n<p>Crie um programa para cadastrar 10 contatos, contendo nome e telefone. Depois, permita pesquisar um nome e exibir o telefone correspondente.</p>\n<span class=\"badge\" title=\"Use dois vetores relacionados pela mesma posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 159 — Jogo de Adivinhação</strong>\n<p>Defina um número secreto dentro do programa. O usuário deve tentar adivinhar o número. A cada tentativa, informe se o valor digitado é maior ou menor que o número secreto. O jogo termina quando acertar.</p>\n<span class=\"badge\" title=\"Use repetição com condição de parada.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 160 — Sistema de Notas com Funções</strong>\n<p>Crie um programa modularizado para calcular a média de um aluno. Use uma função para calcular a média e um função sem retorno para exibir o relatório final.</p>\n<span class=\"badge\" title=\"Separe cálculo e exibição em partes diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 161 — Controle de Despesas</strong>\n<p>Leia os gastos de uma pessoa durante 12 meses. Ao final, exiba o total gasto no ano, a média mensal e o mês com maior despesa.</p>\n<span class=\"badge\" title=\"Um vetor pode representar os meses do ano.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 162 — Temperaturas do Mês</strong>\n<p>Leia as temperaturas registradas em 30 dias. Exiba a maior temperatura, a menor temperatura, a média e quantos dias ficaram acima da média.</p>\n<span class=\"badge\" title=\"Talvez seja necessário percorrer os dados mais de uma vez.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 163 — Urna Eletrônica Simples</strong>\n<p>Crie um programa que simule uma votação com três candidatos. Leia os votos de 20 eleitores e informe o total de votos de cada candidato e o vencedor.</p>\n<span class=\"badge\" title=\"Cada candidato precisa de um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 164 — Ranking de Alunos</strong>\n<p>Leia o nome e a média de 10 alunos. Exiba o aluno com maior média, o aluno com menor média e a média geral da turma.</p>\n<span class=\"badge\" title=\"Guarde nome e nota na mesma posição lógica.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 165 — Estacionamento</strong>\n<p>Um estacionamento possui 5 fileiras com 6 vagas. Leia a ocupação das vagas usando 0 para livre e 1 para ocupada. Ao final, informe o total de vagas livres e ocupadas.</p>\n<span class=\"badge\" title=\"A matriz representa o espaço físico do estacionamento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 166 — Controle de Produtos Vencidos</strong>\n<p>Cadastre 10 produtos com nome, quantidade e dias restantes para vencimento. Ao final, informe quais produtos vencem em até 7 dias.</p>\n<span class=\"badge\" title=\"Use uma decisão durante a exibição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 167 — Simulador de Atendimento</strong>\n<p>Um sistema deve registrar 15 atendimentos. Para cada atendimento, leia o tempo gasto em minutos. Ao final, informe o tempo médio, o maior tempo e o menor tempo.</p>\n<span class=\"badge\" title=\"É um exercício de estatística com repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 168 — Pedido de Lanchonete</strong>\n<p>Crie um programa com um menu de produtos. O usuário deve escolher itens e quantidades. O pedido termina quando escolher a opção sair. Ao final, exiba o total da compra.</p>\n<span class=\"badge\" title=\"Use repetição enquanto o usuário não escolher sair.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 169 — Análise de Números</strong>\n<p>Leia 20 números inteiros e informe quantos são positivos, negativos, pares, ímpares e múltiplos de 5.</p>\n<span class=\"badge\" title=\"Um mesmo número pode entrar em mais de uma classificação.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 170 — Projeto Livre</strong>\n<p>Crie um programa próprio usando pelo menos três conteúdos estudados no módulo, como decisão, repetição, lista, lista de listas ou função. O programa deve ter entrada de dados, processamento e saída organizada.</p>\n<span class=\"badge\" title=\"Pense primeiro no problema, depois nos dados necessários e só então nos comandos.\">💡 Dica</span>\n</div></section>\n</div>\n"}];

const menu = document.getElementById('menu');
const exerciseLevels=[
  {id:'py-ex-level-1',label:'Fundamentos'},
  {id:'py-ex-level-2',label:'Decisão'},
  {id:'py-ex-level-3',label:'Repetição'},
  {id:'py-ex-level-4',label:'Listas (vetores)'},
  {id:'py-ex-level-5',label:'Listas de listas (matrizes)'},
  {id:'py-ex-level-6',label:'Funções'},
  {id:'py-ex-level-7',label:'Desafios'}
];
function isMobileMenu(){return window.matchMedia('(max-width:1050px)').matches;}
function positionExercisesMenu(){
 const group=document.querySelector('.python-exercises-group'); if(!group||!isMobileMenu())return;
 const btn=group.querySelector('.nav-toggle'),tree=group.querySelector('.nav-tree'),r=btn.getBoundingClientRect();
 tree.style.setProperty('--submenu-left',Math.max(12,Math.min(r.left,window.innerWidth-292))+'px');
 tree.style.setProperty('--submenu-top',(r.bottom+6)+'px');
}
function toggleExerciseMenu(){const g=document.querySelector('.python-exercises-group');if(!g)return;g.classList.toggle('open');positionExercisesMenu();}
function buildMenu(){
 steps.forEach((s,i)=>{
  if(s.id===99){
   const group=document.createElement('div');group.className='nav-group python-exercises-group';
   const b=document.createElement('button');b.className='nav-btn nav-toggle';b.id='btn-99';b.innerHTML='<span>99 Exercícios</span><span class="nav-caret">▶</span>';
   b.onclick=()=>{render(i);toggleExerciseMenu();};group.appendChild(b);
   const tree=document.createElement('div');tree.className='nav-tree';
   exerciseLevels.forEach(l=>{const a=document.createElement('button');a.className='nav-sub';a.dataset.level=l.id;a.textContent=l.label;a.onclick=e=>{e.stopPropagation();goToExerciseLevel(l.id);};tree.appendChild(a);});
   group.appendChild(tree);menu.appendChild(group);return;
  }
  const b=document.createElement('button');b.className='nav-btn';b.id='btn-'+s.id;b.textContent=s.title.replace(/^\d+\.\s*/, '');b.onclick=()=>render(i);menu.appendChild(b);
 });
}
function esc(t){return (t||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');}
function prepareExerciseLevels(){document.querySelectorAll('.exercises-99 .exercise-level').forEach((x,i)=>{if(exerciseLevels[i])x.id=exerciseLevels[i].id;});}
function goToExerciseLevel(id){const i=steps.findIndex(s=>s.id===99);render(i);document.querySelectorAll('.nav-sub').forEach(x=>x.classList.toggle('active',x.dataset.level===id));const t=document.getElementById(id),view=document.querySelector('.theory-view');if(!t||!view)return;if(isMobileMenu()){window.scrollTo({top:t.getBoundingClientRect().top+scrollY-110,behavior:'auto'});document.querySelector('.python-exercises-group')?.classList.remove('open');}else view.scrollTo({top:Math.max(0,t.offsetTop-18),behavior:'auto'});}
function render(i){
 const s=steps[i];document.querySelectorAll('.nav-btn,.nav-sub').forEach(b=>b.classList.remove('active'));document.getElementById('btn-'+s.id)?.classList.add('active');
 document.getElementById('stepTitle').textContent=s.title;document.getElementById('objective').innerHTML='<strong>Objetivo:</strong> '+s.objective;
 const w=document.getElementById('workspace');
 if(s.type==='theory'){w.innerHTML=`<section class="theory-view">${s.html}</section>`;if(s.id===99)prepareExerciseLevels();return;}
 w.innerHTML=`<section class="code-card card"><div class="panel-title"><span>Editor do IDLE — arquivo .py</span><button class="btn-copy" onclick="copyText('fullCode')">Copiar</button></div><pre id="fullCode">${esc(s.code)}</pre></section><section class="idle-card card"><div class="idle-title">🐍 Python IDLE — Shell</div><div class="idle-window"><div class="idle-bar">Python Shell</div><div class="shell" id="shellOut">${esc(s.output)}</div></div></section><section class="work-card card"><div class="panel-title"><span>O que foi trabalhado</span></div><div class="work-content">${s.work}</div></section><aside class="exercise-card"><h3>Exercício proposto</h3><p>${s.exercise}</p></aside>`;
}
function copyText(id){const el=document.getElementById(id);navigator.clipboard.writeText(el.textContent);}
buildMenu();window.addEventListener('resize',positionExercisesMenu);document.addEventListener('click',e=>{const g=document.querySelector('.python-exercises-group');if(g&&!g.contains(e.target)&&isMobileMenu())g.classList.remove('open');});render(0);
